const express = require('express');
const router = express.Router();
const sql = require('mssql');

router.get('/api/production/yearly-summary', async (req, res) => {
  try {
    const { clusterId, lineId, yearRange } = req.query;
    const parsedYearRange = yearRange ? parseInt(yearRange, 10) : 5;

    if (isNaN(parsedYearRange) || parsedYearRange <= 0) {
      return res.status(400).json({ success: false, message: 'Invalid yearRange parameter provided.' });
    }

    const pool = await sql.connect();
    const request = pool.request();

    request.input('ClusterId', sql.VarChar(50), clusterId || null);
    request.input('LineId', sql.VarChar(50), lineId || null);
    request.input('YearRange', sql.Int, parsedYearRange);
    request.input('CurrentYear', sql.Int, new Date().getFullYear());

    const query = `
      SELECT 
        COALESCE(YEAR(p.ProductionDate), @CurrentYear) AS [Year], 
        SUM(ISNULL(p.ActualOutput, 0)) AS [TotalActual], 
        SUM(ISNULL(p.TargetOutput, 0)) AS [TotalTarget], 
        ROUND(AVG(ISNULL(p.OeePercentage, 0.0)), 2) AS [AvgOee], 
        COUNT(p.ProductionId) AS [TotalRuns] 
      FROM dbo.ProductionMetrics p 
      WHERE (@ClusterId IS NULL OR p.ClusterId = @ClusterId) 
        AND (@LineId IS NULL OR p.LineId = @LineId) 
        AND p.ProductionDate >= DATEADD(year, -@YearRange, GETDATE()) 
      GROUP BY YEAR(p.ProductionDate) 
      ORDER BY [Year] DESC;
    `;

    const result = await request.query(query);

    return res.status(200).json({
      success: true,
      filter: 'yearly',
      data: result.recordset.map(row => ({
        year: row.Year,
        totalActual: row.TotalActual,
        totalTarget: row.TotalTarget,
        avgOee: row.AvgOee,
        totalRuns: row.TotalRuns
      }))
    });
  } catch (error) {
    console.error('Database aggregation error:', error);
    return res.status(500).json({ success: false, message: 'Internal Server Error', error: error.message });
  }
});

module.exports = router;

